explicit_new_block:
a = actual.a_matrix_
native_starts = list(a.start_)
native_indices = list(a.index_)
native_values = list(a.value_)
restored = [[] for _ in rows]
assert len(native_indices) == len(native_values) == len(indices)
if a.format_ == highspy.MatrixFormat.kRowwise:
    assert len(native_starts) == len(rows) + 1
    for i in range(len(rows)):
        for k in range(native_starts[i], native_starts[i + 1]):
            assert native_values[k] == 1.0 and 0 <= native_indices[k] < n
            restored[i].append(int(native_indices[k]))
else:
    assert a.format_ == highspy.MatrixFormat.kColwise and len(native_starts) == n + 1
    for j in range(n):
        for k in range(native_starts[j], native_starts[j + 1]):
            assert native_values[k] == 1.0 and 0 <= native_indices[k] < len(rows)
            restored[int(native_indices[k])].append(j)
assert [sorted(r) for r in restored] == [r["columns"] for r in rows]
assert all(len(r) == len(set(r)) for r in restored)

